import{_ as t,o as n,c as a,a5 as o}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"Plan — FR 3.3.3: View Client Profile","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/02-profile/3-3-3-view-client-profile/plan.md","filePath":"feature/srs/02-profile/3-3-3-view-client-profile/plan.md"}'),i={name:"feature/srs/02-profile/3-3-3-view-client-profile/plan.md"};function d(r,e,l,c,s,h){return n(),a("div",null,[...e[0]||(e[0]=[o(`<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <a href="./spec.html">Spec</a> · <strong>Plan</strong> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="plan-—-fr-3-3-3-view-client-profile" tabindex="-1">Plan — FR 3.3.3: View Client Profile <a class="header-anchor" href="#plan-—-fr-3-3-3-view-client-profile" aria-label="Permalink to &quot;Plan — FR 3.3.3: View Client Profile&quot;">​</a></h1><p>&gt; Liên kết: <a href="./spec.html">spec.md</a> — hiển thị danh sách Client Profile của User đang đăng nhập, và danh sách Client đang cộng tác trong 1 workspace. &gt; &gt; V2 (2026-10-02): <strong>[SỬA]</strong> ClientProfile không còn ràng buộc <code>agency_id</code> — thuộc sở hữu User, độc lập Agency, dùng được ở nhiều workspace/agency. Xem <a href="#6-lịch-sử-thay-đổi">§6</a> cho lý do.</p><h2 id="_1-pham-vi-ky-thuat" tabindex="-1">1. Phạm vi kỹ thuật <a class="header-anchor" href="#_1-pham-vi-ky-thuat" aria-label="Permalink to &quot;1. Phạm vi kỹ thuật&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Repo</td><td><code>brandhub-business-service</code>, <code>brandhub-web</code></td></tr><tr><td>File implement</td><td><code>ClientProfileServiceImpl.listMine()</code></td></tr><tr><td>File liên quan</td><td><code>ClientProfileController</code> (<code>GET /api/v1/client-profile/mine</code>), <code>ClientProfileResponse</code>, <code>WorkspaceController</code> (<code>GET /api/v1/workspaces/{id}/members</code> — dùng chung cho Workspace Client list, filter role CLIENT ở FE)</td></tr></tbody></table><h2 id="_2-api-contract-final" tabindex="-1">2. API Contract (final) <a class="header-anchor" href="#_2-api-contract-final" aria-label="Permalink to &quot;2. API Contract (final)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/v1/client-profile/mine</span></span>
<span class="line"><span>Authorization: Bearer &lt;access-token&gt;</span></span>
<span class="line"><span>→ 200 ApiResponse&lt;ClientProfileResponse[]&gt;</span></span>
<span class="line"><span>   data = [{ id, userId, displayName, company, phone, note, logoUrl, website, industry,</span></span>
<span class="line"><span>             location, description, socialLinks, contactName, contactEmail, companySize,</span></span>
<span class="line"><span>             instagramUrl, taxCode, address, tagline, foundedYear, budgetRange,</span></span>
<span class="line"><span>             createdAt, updatedAt }, ...]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>GET /api/v1/workspaces/{workspaceId}/members</span></span>
<span class="line"><span>→ 200 ApiResponse&lt;WorkspaceMemberResponse[]&gt;</span></span>
<span class="line"><span>   (FE lọc role === &quot;CLIENT&quot; cho trang /workspaces/:id/clients)</span></span></code></pre></div><p>Không còn <code>email</code> trên <code>ClientProfileResponse</code> — email lấy từ <code>User</code> (authStore) của chính người sở hữu profile.</p><h2 id="_3-data-model" tabindex="-1">3. Data Model <a class="header-anchor" href="#_3-data-model" aria-label="Permalink to &quot;3. Data Model&quot;">​</a></h2><p><code>client_profiles</code> — <strong>[SỬA 2026-10-02]</strong> bỏ hẳn <code>agency_id</code> (migration <code>2026-10-02-drop-client-profile-agency-id.sql</code>). ClientProfile chỉ còn gắn với <code>user_id</code>, không ràng buộc Agency:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Note</th></tr></thead><tbody><tr><td>id</td><td>UUID</td><td>PK</td></tr><tr><td>user_id</td><td>UUID</td><td>FK <code>users</code> — chủ sở hữu duy nhất</td></tr><tr><td>display_name</td><td>varchar</td><td>not null</td></tr><tr><td>company</td><td>varchar</td><td>null</td></tr><tr><td>phone</td><td>varchar</td><td>null</td></tr><tr><td>note</td><td>text</td><td>null</td></tr><tr><td>logo_url</td><td>varchar</td><td>null — logo công ty</td></tr><tr><td>website</td><td>varchar</td><td>null — website công ty</td></tr><tr><td>industry</td><td>varchar</td><td>null — ngành nghề</td></tr><tr><td>location</td><td>varchar</td><td>null — địa điểm</td></tr><tr><td>description</td><td>text</td><td>null — mô tả công ty</td></tr><tr><td>social_links</td><td>jsonb</td><td>null — <code>{ &quot;linkedin&quot;, &quot;facebook&quot; }</code></td></tr><tr><td>contact_name / contact_email / company_size / instagram_url / tax_code / address / tagline / founded_year / budget_range</td><td>—</td><td>field thương hiệu bổ sung (2026-09-27)</td></tr><tr><td>created_at / updated_at</td><td>timestamptz</td><td></td></tr></tbody></table><p>Quan hệ với workspace: <code>workspace_members.client_profile_id</code> (FK, nullable) — 1 ClientProfile có thể là target của nhiều <code>workspace_members</code> row ở nhiều workspace/agency khác nhau cùng lúc. <code>ClientProfileRepository.findByUserId(userId)</code> trả toàn bộ profile của 1 user, không filter theo agency.</p><h2 id="_4-luong-xu-ly" tabindex="-1">4. Luồng xử lý <a class="header-anchor" href="#_4-luong-xu-ly" aria-label="Permalink to &quot;4. Luồng xử lý&quot;">​</a></h2><p><strong>My Brand Profiles:</strong></p><ol><li><code>findByUserId(currentUser.getId())</code> → trả list (rỗng nếu chưa tạo profile nào).</li><li>Map từng record → <code>ClientProfileResponse</code>.</li></ol><p><strong>Workspace Client list:</strong></p><ol><li><code>WorkspaceService.listMembers(workspaceId)</code> → trả toàn bộ <code>WorkspaceMember</code> active.</li><li>FE lọc <code>role === &quot;CLIENT&quot;</code>, hiển thị <code>fullName</code> (resolve từ ClientProfile liên kết qua <code>clientProfileId</code>).</li></ol><h2 id="_5-dependencies" tabindex="-1">5. Dependencies <a class="header-anchor" href="#_5-dependencies" aria-label="Permalink to &quot;5. Dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Chiều</th><th>Mô tả</th></tr></thead><tbody><tr><td>Chặn bởi</td><td><code>ClientProfile</code> entity, <code>ClientProfileRepository</code></td></tr><tr><td>Bị chặn</td><td><code>Update Client Profile</code> (3.3.4), <code>Invite Agency Member</code> (3.4.7) khi role CLIENT</td></tr></tbody></table><h2 id="_6-lich-su-thay-đoi" tabindex="-1">6. Lịch sử thay đổi <a class="header-anchor" href="#_6-lich-su-thay-đoi" aria-label="Permalink to &quot;6. Lịch sử thay đổi&quot;">​</a></h2><ul><li><strong>2026-09-21</strong> (đã revert): từng thêm <code>agency_id</code> vào <code>client_profiles</code>, model 1-profile/agency. Sai nghiệp vụ thật — Nike/Adidas không có tài khoản riêng, chỉ có người đại diện (1 User) sở hữu nhiều ClientProfile (mỗi brand 1 cái), dùng xuyên suốt nhiều Agency.</li><li><strong>2026-10-02:</strong> xoá <code>agency_id</code>, chuyển hẳn sang mô hình User-owned, N-per-user. Đồng thời tách trang Thành viên (<code>/workspaces/:id/members</code>, chỉ nội bộ) và trang Client (<code>/workspaces/:id/clients</code>, CLIENT collaborator) thành 2 route độc lập — trước đó gộp chung 1 trang với tab switcher.</li></ul><h2 id="tich-hop-frontend-web-mobile-đa-trien-khai" tabindex="-1">Tích hợp Frontend Web &amp; Mobile (Đã triển khai) <a class="header-anchor" href="#tich-hop-frontend-web-mobile-đa-trien-khai" aria-label="Permalink to &quot;Tích hợp Frontend Web &amp; Mobile (Đã triển khai)&quot;">​</a></h2><ul><li><strong>Web (<code>brandhub-web</code>):</strong> <code>src/pages/workspace/client-profile.tsx</code>, <code>src/pages/workspace/clients.tsx</code>, <code>src/pages/workspace/components/{ClientsSection,ClientsTable,ClientProfileViewModal}.tsx</code>, <code>src/services/clientProfileService.ts</code> — đồng bộ song song locale <code>vi</code>/<code>en</code> (<code>clientProfile.* / workspace.clients.*</code>) và semantic Light/Dark mode tokens.</li><li><strong>Mobile (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/more/{ClientsScreen,ClientProfileScreen}.tsx</code>, <code>src/services/clientProfileService.ts</code> — đồng bộ API contract, token state và kiểm tra lỗi nhất quán với Web.</li><li><strong>Tài liệu tham chiếu:</strong> <a href="./../../../../ba/02-authentication-profile.html">BA Authentication &amp; Profile</a> · <a href="./../../../modules/README.html">Module Specs Index</a> · <a href="./test.html">Test Suite</a>.</li></ul>`,23)])])}const g=t(i,[["render",d]]);export{u as __pageData,g as default};
